def _resolve_role_abbrev(role: Any) -> Optional[str]:
    """The role abbrev for either spelling of a legacy role name, or None."""
    key = str(role or "").strip().lower()
    if key in ROLE_NAMES:
        return key
    return _ROLE_ABBREV_BY_NAME.get(key)


def profile_pair_for_role(role: Any) -> Tuple[str, str]:
    """The `(stage_profile, capability_profile)` pair a legacy role name
    projects onto at dispatch time. Accepts both spellings: the receipt
    abbrev ("se") and the full agent name ("software-engineer").

    This is the single alias surface the pilot allows the nine names to
    survive through (capability-profile-pilot.md 3.1): dispatch and advance
    key on the pair; the names stay wire-compatible aliases. Built on the
    DISPATCH_* projection tables above, never a second copy of them.

    Raises ValueError for a name outside the table, naming both accepted
    spellings, so a typo is refused with a route to the fix rather than
    silently projected onto nothing. Also ValueError -- not KeyError -- when
    the name IS a legacy role but one of the projection tables has no row for
    it: an incomplete projection is a table bug, and #402 made the kernel's
    gate depend on this call, so it has to fail in the shape callers already
    handle rather than as an unhandled lookup.
    """
    abbrev = _resolve_role_abbrev(role)
    if abbrev is None:
        raise ValueError(
            "role: %r is not a legacy role name; expected a role abbrev in "
            "%s or a full agent name in %s"
            % (role, sorted(ROLE_NAMES), sorted(ROLE_NAMES.values()))
        )
    stage_profile = DISPATCH_STAGE_PROFILE.get(abbrev)
    capability_profile = DISPATCH_CAPABILITY_PROFILE.get(abbrev)
    if stage_profile is None or capability_profile is None:
        raise ValueError(
            "role: %r has an incomplete dispatch projection (stage_profile=%r, "
            "capability_profile=%r); both tables must carry every role in %s"
            % (role, stage_profile, capability_profile, sorted(ROLE_NAMES))
        )
    return (stage_profile, capability_profile)


def roles_for_profile_pair(stage_profile: Any, capability_profile: Any) -> Tuple[str, ...]:
    """The role abbrevs that project onto `(stage_profile, capability_profile)`,
    sorted, possibly empty: a valid pair no role projects onto (for example
    admitting/analyst) returns () because the projection is total over roles,
    not over pairs.

    Raises ValueError when either profile is outside its vocabulary: a typo'd
    profile silently yielding () would read as "no roles here" instead of
    "that profile does not exist".
    """
    stage_key = str(stage_profile or "").strip().lower()
    capability_key = str(capability_profile or "").strip().lower()
    if stage_key not in STAGE_PROFILES:
        raise ValueError(
            "stage_profile: %r not in %r" % (stage_profile, STAGE_PROFILES)
        )
    if capability_key not in CAPABILITY_PROFILES:
        raise ValueError(
            "capability_profile: %r not in %r"
            % (capability_profile, CAPABILITY_PROFILES)
        )
    return tuple(
        abbrev
        for abbrev in sorted(DISPATCH_CAPABILITY_PROFILE)
        if DISPATCH_STAGE_PROFILE[abbrev] == stage_key
        and DISPATCH_CAPABILITY_PROFILE[abbrev] == capability_key
    )


def _accountable_role_problems(value: Any) -> List[str]:
    """Problems with an accountable_role value that IS present. Absence is
    never a problem here: the field is soft-required during the migration
    window (the #342 overlay pattern), so only a value outside the alias
    table refuses."""
    if not isinstance(value, str) or _resolve_role_abbrev(value) is None:
        return [
            "accountable_role: %r is not in the role-alias table (accepted: "
            "role abbrevs %s or full agent names %s); the field is "
            "soft-required during the migration window, so omit it rather "
            "than guessing a value"
            % (value, sorted(ROLE_NAMES), sorted(ROLE_NAMES.values()))
        ]
    return []

