# ── the bridge's attempt record, as a host may trust it ──────────────────────

# What an attempt record must agree with the envelope about before anything it
# reports may be projected onto the board. All four, because the useful lie is
# a partial one: a record that names the right story and role but a different
# attempt is exactly the shape that made a superseded generation look current.
ATTEMPT_RECORD_IDENTITY = ("attempt_id", "dispatch_id", "story_id", "role")


def attempt_record_disagreements(envelope: Any, attempt: Any) -> List[str]:
    """Why this attempt record does not describe the requested envelope.

    A host asks the bridge to run one envelope and reads a record back. The
    two are separate documents from separate processes, and the record is
    whatever the bridge printed, so the host must establish that they name the
    same work before it projects the record's generation and state onto the
    dispatch binding.

    The first version of that caller took `fencing_token` and `state` from the
    record but `attempt_id`, story and role from the ENVELOPE, which relabelled
    whatever the bridge reported as the requested attempt and neutralised the
    kernel's exact-attempt guard: supply envelope A, return a record for B, and
    B's generation landed on A's binding (#396).

    ABSENCE IS NOT A MATCH. A record that omits a field cannot establish that
    it names this work, so a missing value is a disagreement rather than a
    waiver -- the same rule the kernel applies to a binding with no attempt id.
    """
    if not isinstance(envelope, dict):
        return ["no envelope to compare the attempt record against"]
    if not isinstance(attempt, dict):
        return ["the bridge reported no attempt record"]
    problems: List[str] = []
    for field in ATTEMPT_RECORD_IDENTITY:
        want = str(envelope.get(field) or "").strip()
        got = str(attempt.get(field) or "").strip()
        if not want:
            problems.append(
                "the envelope names no %s, so nothing here can confirm the "
                "attempt record describes it" % field
            )
            continue
        if not got:
            problems.append(
                "the attempt record reports no %s, so it cannot be confirmed "
                "as the record for %s" % (field, want)
            )
            continue
        if got != want:
            problems.append(
                "the attempt record reports %s %s but the envelope requested "
                "%s" % (field, got, want)
            )
    return problems


def attempt_close_confirmed(attempt: Any) -> bool:
    """Whether the control plane confirmed this attempt's terminal close.

    An attempt record's `state` is what the process decided locally. It is not
    evidence that the control plane accepted it, and the two diverge exactly
    when it matters: a holder fenced out mid-run, or one asked to cancel, can
    still finish its adapter and describe itself as `completed` while the
    control plane has already given the attempt to someone else. Only the
    fenced close (or the fenced cancel acknowledgement) settles it, so the
    record carries that bit and a projection reads this rather than the state.

    `is True` on purpose: a JSON string is truthy, and `"false"` reading as
    confirmed is the same class of bug as a snapshot's `available: "false"`
    selecting a runtime.
    """
    return isinstance(attempt, dict) and attempt.get("cp_closed") is True


