def _receipt_required_fields() -> List[str]:
    """The evidence contract's required receipt fields, or () if unreadable.

    Never raises and never guesses. An unreadable contract yields an empty
    list, which every reader is told to treat as "do not pre-judge" rather than
    as "nothing is required": the kernel validates the same document at advance
    either way, so the cost of an unreadable contract is earliness, not
    enforcement.
    """
    try:
        import evidence_contract  # noqa: PLC0415

        fields = evidence_contract.load_contract().get("receipt", {}).get(
            "required_fields", []
        )
    except Exception:  # noqa: BLE001
        return []
    return [str(f) for f in fields if isinstance(f, str) and f.strip()]


